(function () {
    var visited = "is";
    var countriesString = "DE";
    var countriesArray = countriesString.split(',');
    var countryMatch = false;
    var expectedType = "WEB";
    var expectedStatus = "OPEN";
    if (request && request.params && request.params.geo && request.params.geo.country) {
      for (var p = 0; p < countriesArray.length; p++) {
          if (request.params.geo.country === countriesArray[p].trim()) {	
              countryMatch = true;
              break;
          }
      }
    } else if (guest && guest.sessions && guest.sessions.length > 0) {
        loop:
        for (var i = 0; i < guest.sessions.length; i++) {
            if (guest.sessions[i]) {
                if (
                    guest.sessions[i].sessionType !== expectedType
                    || guest.sessions[i].status !== expectedStatus
                ) {
                    continue loop;
                } else if (
                    guest.sessions[i].dataExtensions
                ) {
                    for (var j = 0; j < guest.sessions[i].dataExtensions.length; j++) {
                       if (guest.sessions[i].dataExtensions[j].key && guest.sessions[i].dataExtensions[j].key === 'bxt') {
                           if (guest.sessions[i].dataExtensions[j].values && guest.sessions[i].dataExtensions[j].values.geoLocationCountry) {
                               for (var k = 0; k < countriesArray.length; k++) {	
                                    if (guest.sessions[i].dataExtensions[j].values.geoLocationCountry === countriesArray[k].trim()) {	
                                        countryMatch = true;
                                        break;
                                    }
                                }
                           }
                       } 
                    }
                }
            }
        }
    }
    return (visited === "is") && countryMatch || (visited === "is not") && !countryMatch;
})();
